
from __future__ import annotations

from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
HTML = ROOT / "docs" / "index.html"
SINGLE_JS = '<script id="ml-rank-accordion-single-controller">\n(function(){\n  const MODEL_ORDER=[\'Ensemble\',\'Score Top\',\'Ridge\',\'Random Forest\',\'Extra Trees\',\'XGBoost\',\'LightGBM\',\'CatBoost\'];\n\n  function addStyle(){\n    if(document.getElementById(\'mlRankAccordionSingleStyle\')) return;\n    const style=document.createElement(\'style\');\n    style.id=\'mlRankAccordionSingleStyle\';\n    style.textContent=`\n      .ml-rank-badge{display:inline-flex;align-items:center;justify-content:center;min-width:32px;height:26px;padding:0 8px;border-radius:999px;background:rgba(34,197,94,.12);border:1px solid rgba(34,197,94,.35);color:#86efac;font-weight:900;margin-right:10px;font-size:.82rem;flex:0 0 auto}\n      .ml-acc-card{margin:14px 0 16px;border:1px solid rgba(148,163,184,.18);border-radius:16px;background:rgba(15,23,42,.35);overflow:hidden}\n      .ml-acc-head{width:100%;border:0;background:transparent;color:inherit;cursor:pointer;padding:14px 16px;font:inherit;font-weight:800;display:flex;align-items:center;justify-content:space-between;gap:12px;text-align:left}\n      .ml-acc-head:hover{background:rgba(148,163,184,.06)}\n      .ml-acc-title{display:inline-flex;align-items:center;gap:0}\n      .ml-acc-meta{color:var(--muted);font-weight:600;font-size:.86rem;margin-left:auto}\n      .ml-acc-head::after{content:\'+\';font-weight:900;color:var(--muted);margin-left:12px}\n      .ml-acc-card.is-open .ml-acc-head{border-bottom:1px solid rgba(148,163,184,.14)}\n      .ml-acc-card.is-open .ml-acc-head::after{content:\'−\'}\n      .ml-acc-body{display:none}\n      .ml-acc-card.is-open .ml-acc-body{display:block}\n      .ml-acc-card .table-wrap{margin:0}\n      .ml-perf-sub{display:block;color:var(--muted);font-size:.78rem;margin-top:2px;font-weight:600}\n      .ml-perf-status{display:inline-flex;align-items:center;border-radius:999px;padding:4px 8px;font-weight:800;font-size:.78rem;border:1px solid rgba(148,163,184,.22)}\n      .ml-perf-status.ok{color:#86efac;background:rgba(34,197,94,.10);border-color:rgba(34,197,94,.28)}\n      .ml-perf-status.warm{color:#fbbf24;background:rgba(251,191,36,.10);border-color:rgba(251,191,36,.28)}\n      .ml-perf-status.na{color:#94a3b8;background:rgba(148,163,184,.08)}\n      .ml-perf-help{margin:10px 0 14px;color:var(--muted);font-size:.9rem;line-height:1.45}\n      .ml-perf-help b{color:var(--text)}\n    `;\n    document.head.appendChild(style);\n  }\n\n  function asNumber(v){\n    if(v===null || v===undefined || v===\'\') return null;\n    if(typeof v===\'number\') return Number.isFinite(v) ? v : null;\n    let s=String(v).trim();\n    if(!s || [\'nan\',\'none\',\'null\',\'-\',\'—\',\'<na>\'].includes(s.toLowerCase())) return null;\n    s=s.replace(\'R$\',\'\').replace(\'%\',\'\').replace(/\\s/g,\'\');\n    s=s.replace(/[^0-9,.\\-+]/g,\'\');\n    if(!s || [\',\',\'.\',\'-\',\'+\'].includes(s)) return null;\n    if(s.includes(\',\') && s.includes(\'.\')){\n      if(s.lastIndexOf(\',\') > s.lastIndexOf(\'.\')) s=s.replace(/\\./g,\'\').replace(\',\',\'.\');\n      else s=s.replace(/,/g,\'\');\n    }else if(s.includes(\',\')){\n      s=s.replace(/\\./g,\'\').replace(\',\',\'.\');\n    }else{\n      const parts=s.split(\'.\');\n      if(parts.length>2) s=parts.slice(0,-1).join(\'\')+\'.\'+parts.at(-1);\n    }\n    const n=Number(s);\n    return Number.isFinite(n) ? n : null;\n  }\n\n  function avg(values){\n    const nums=values.map(asNumber).filter(v=>v!==null);\n    if(!nums.length) return null;\n    return nums.reduce((a,b)=>a+b,0)/nums.length;\n  }\n\n  function maxNum(values){\n    const nums=values.map(asNumber).filter(v=>v!==null);\n    if(!nums.length) return null;\n    return Math.max(...nums);\n  }\n\n  function fmtNum(v,d=2){\n    const n=asNumber(v);\n    if(n===null) return \'—\';\n    return n.toLocaleString(\'pt-BR\',{minimumFractionDigits:d,maximumFractionDigits:d});\n  }\n\n  function fmtPct(v){\n    const n=asNumber(v);\n    if(n===null) return \'—\';\n    const pct=Math.abs(n)<=1.5 ? n*100 : n;\n    return (pct>0?\'+\':\'\')+pct.toLocaleString(\'pt-BR\',{minimumFractionDigits:2,maximumFractionDigits:2})+\'%\';\n  }\n\n  function fmtHit(v){\n    const n=asNumber(v);\n    if(n===null) return \'—\';\n    const pct=Math.abs(n)<=1.5 ? n*100 : n;\n    return pct.toLocaleString(\'pt-BR\',{minimumFractionDigits:2,maximumFractionDigits:2})+\'%\';\n  }\n\n  function modelFromText(text){\n    const clean=String(text||\'\').replace(/#\\d+/g,\'\').trim().toLowerCase();\n    return MODEL_ORDER.find(m=>clean.includes(m.toLowerCase())) || null;\n  }\n\n  function statusClass(status){\n    const s=String(status||\'\').toLowerCase();\n    if(s.includes(\'ativo\') || s.includes(\'ok\')) return \'ok\';\n    if(s.includes(\'aquec\') || s.includes(\'matur\')) return \'warm\';\n    return \'na\';\n  }\n\n  function payloadFromState(){\n    try{\n      if(typeof state!==\'undefined\' && state && state.data && state.data.modelos_ml) return state.data;\n    }catch(e){}\n    return null;\n  }\n\n  async function loadPayload(){\n    const s=payloadFromState();\n    if(s) return s;\n    try{\n      const idx=await fetch(\'data/index.json\',{cache:\'no-store\'}).then(r=>r.json());\n      const latest=[...idx].sort().at(-1);\n      return await fetch(`data/${latest}.json`,{cache:\'no-store\'}).then(r=>r.json());\n    }catch(e){\n      return null;\n    }\n  }\n\n  function getPerfRows(ml){\n    const rows=Array.isArray(ml?.performance) ? ml.performance : [];\n    return rows.map(r=>{\n      const raw=r.Modelo ?? r.modelo ?? r.model;\n      const model=raw ? (MODEL_ORDER.find(m=>String(raw).toLowerCase().includes(m.toLowerCase())) || String(raw).trim()) : null;\n      if(!model) return null;\n      return {\n        model,\n        type:String(r.Tipo ?? r.tipo ?? r.Classe ?? r.classe ?? \'—\').replace(\'ACAO\',\'Ações\').replace(\'FII\',\'FIIs\'),\n        horizon:String(r.Horizonte ?? r.horizonte ?? ml?.horizonte_principal ?? \'7d\'),\n        retorno:asNumber(r.Retorno_Medio_Top20 ?? r.retorno_medio_top20 ?? r.retorno_medio ?? r.Return_Top20),\n        hit:asNumber(r.Hit_Rate_Top20 ?? r.hit_rate_top20 ?? r.hit_rate ?? r.Hit_Rate),\n        spearman:asNumber(r.Spearman_IC ?? r.spearman_ic ?? r.IC),\n        alpha:asNumber(r.Alpha_vs_Score_Top ?? r.alpha_vs_score_top ?? r.Alpha),\n        confianca:asNumber(r.Confiabilidade_Pct ?? r.confiabilidade_pct ?? r.Confiabilidade),\n        janelas:asNumber(r.Janelas_Validas ?? r.janelas_validas ?? r.Valid_Windows ?? r.valid_windows),\n        status:String(r.Status ?? r.status ?? r.status_modelos ?? \'—\')\n      };\n    }).filter(Boolean);\n  }\n\n  function modelStats(ml){\n    const perf=getPerfRows(ml);\n    const byModel=new Map();\n\n    for(const row of perf){\n      if(!byModel.has(row.model)){\n        byModel.set(row.model,{model:row.model,types:new Set(),horizons:new Set(),rows:[],order:MODEL_ORDER.indexOf(row.model)});\n      }\n      const g=byModel.get(row.model);\n      g.rows.push(row);\n      if(row.type && row.type!==\'—\') g.types.add(row.type);\n      if(row.horizon) g.horizons.add(row.horizon);\n    }\n\n    for(const model of MODEL_ORDER){\n      if(!byModel.has(model)){\n        byModel.set(model,{model,types:new Set(),horizons:new Set(),rows:[],order:MODEL_ORDER.indexOf(model)});\n      }\n    }\n\n    const stats=[...byModel.values()].map(g=>{\n      const rows=g.rows;\n      const out={\n        model:g.model,\n        types:[...g.types],\n        horizons:[...g.horizons],\n        retorno:avg(rows.map(r=>r.retorno)),\n        hit:avg(rows.map(r=>r.hit)),\n        spearman:avg(rows.map(r=>r.spearman)),\n        alpha:avg(rows.map(r=>r.alpha)),\n        confianca:avg(rows.map(r=>r.confianca)),\n        janelas:maxNum(rows.map(r=>r.janelas)),\n        status:rows.some(r=>String(r.status).toLowerCase().includes(\'ativo\')) ? \'Ativo\' : (rows.length ? rows[0].status : \'Sem medição\'),\n        measured:rows.some(r=>[r.retorno,r.hit,r.spearman,r.alpha,r.confianca].some(v=>v!==null)),\n        order:g.order<0 ? 999 : g.order\n      };\n\n      out.sortScore =\n        (out.alpha ?? -999) * 1000 +\n        (out.hit ?? -999) * 100 +\n        (out.spearman ?? -999) * 50 +\n        (out.retorno ?? -999) * 10 +\n        (out.confianca ?? 0);\n\n      return out;\n    });\n\n    stats.sort((a,b)=>{\n      if(a.measured!==b.measured) return a.measured ? -1 : 1;\n      if(b.sortScore!==a.sortScore) return b.sortScore-a.sortScore;\n      return a.order-b.order;\n    });\n\n    stats.forEach((s,i)=>s.rank=i+1);\n    return stats;\n  }\n\n  function renderPerformance(ml,stats){\n    const body=document.getElementById(\'mlPerformanceBody\');\n    if(!body) return;\n\n    const table=body.closest(\'table\');\n    if(table){\n      const thead=table.querySelector(\'thead\');\n      if(thead){\n        thead.innerHTML=`\n          <tr>\n            <th>Rank</th>\n            <th>Modelo</th>\n            <th>Tipos</th>\n            <th>Horizonte</th>\n            <th>Retorno médio Top20</th>\n            <th>Hit rate</th>\n            <th>Spearman IC</th>\n            <th>Alpha vs Score Top</th>\n            <th>Janelas</th>\n            <th>Status</th>\n          </tr>`;\n      }\n    }\n\n    let note=document.getElementById(\'mlPerformanceRankNote\');\n    if(!note && table){\n      note=document.createElement(\'div\');\n      note.id=\'mlPerformanceRankNote\';\n      note.className=\'ml-perf-help\';\n      note.innerHTML=\'<b>Ranking:</b> ordenado do melhor para o pior modelo, priorizando Alpha vs Score Top, Hit Rate, Spearman IC e retorno médio do Top 20. Modelos sem estatística suficiente ficam no fim.\';\n      table.insertAdjacentElement(\'beforebegin\',note);\n    }\n\n    body.innerHTML=stats.map(s=>`\n      <tr>\n        <td><span class="ml-rank-badge">#${s.rank}</span></td>\n        <td><b>${s.model}</b><span class="ml-perf-sub">${s.measured ? \'com estatística calculada\' : \'aguardando medição\'}</span></td>\n        <td>${s.types.length ? s.types.join(\' / \') : \'—\'}</td>\n        <td>${s.horizons.length ? s.horizons.join(\' / \') : (ml.horizonte_principal || \'7d\')}</td>\n        <td class="num">${fmtPct(s.retorno)}</td>\n        <td class="num">${fmtHit(s.hit)}</td>\n        <td class="num">${fmtNum(s.spearman,3)}</td>\n        <td class="num">${fmtPct(s.alpha)}</td>\n        <td class="num">${fmtNum(s.janelas,0)}</td>\n        <td><span class="ml-perf-status ${statusClass(s.status)}">${s.status || \'—\'}</span></td>\n      </tr>\n    `).join(\'\');\n  }\n\n  function metaFromNode(node){\n    const spans=[...node.querySelectorAll(\'span\')].filter(s=>!s.classList.contains(\'ml-rank-badge\') && !s.classList.contains(\'ml-acc-title\'));\n    if(!spans.length) return \'\';\n    return spans[spans.length-1].textContent.trim();\n  }\n\n  function convertDetailsToCards(rankMap){\n    document.querySelectorAll(\'details.static-ml-group, details.force-ml-group, details.ml-model-group\').forEach(detail=>{\n      const summary=detail.querySelector(\':scope > summary\');\n      if(!summary) return;\n\n      const model=modelFromText(summary.textContent);\n      if(!model) return;\n\n      const rank=rankMap.get(model) || \'—\';\n      const meta=metaFromNode(summary);\n\n      const card=document.createElement(\'div\');\n      card.className=\'ml-acc-card\';\n      card.dataset.modelName=model;\n      card.dataset.modelRank=String(rank===\'—\' ? 999 : rank);\n\n      const btn=document.createElement(\'button\');\n      btn.type=\'button\';\n      btn.className=\'ml-acc-head\';\n      btn.dataset.modelName=model;\n      btn.innerHTML=`<span class="ml-acc-title"><span class="ml-rank-badge">#${rank}</span>${model}</span>${meta ? `<span class="ml-acc-meta">${meta}</span>` : \'\'}`;\n\n      const body=document.createElement(\'div\');\n      body.className=\'ml-acc-body\';\n      [...detail.childNodes].forEach(node=>{\n        if(node===summary) return;\n        body.appendChild(node.cloneNode(true));\n      });\n\n      card.appendChild(btn);\n      card.appendChild(body);\n      detail.replaceWith(card);\n    });\n  }\n\n  function decorateCards(rankMap){\n    document.querySelectorAll(\'.ml-acc-card\').forEach(card=>{\n      const btn=card.querySelector(\':scope > .ml-acc-head\');\n      if(!btn) return;\n\n      const model=card.dataset.modelName || btn.dataset.modelName || modelFromText(btn.textContent);\n      if(!model) return;\n\n      const rank=rankMap.get(model) || \'—\';\n      const metaEl=btn.querySelector(\'.ml-acc-meta\');\n      const meta=metaEl ? metaEl.textContent.trim() : \'\';\n\n      card.dataset.modelName=model;\n      card.dataset.modelRank=String(rank===\'—\' ? 999 : rank);\n      btn.dataset.modelName=model;\n      btn.innerHTML=`<span class="ml-acc-title"><span class="ml-rank-badge">#${rank}</span>${model}</span>${meta ? `<span class="ml-acc-meta">${meta}</span>` : \'\'}`;\n    });\n  }\n\n  function reorderCards(){\n    [\'staticMlModelTables\',\'forceMlModelByModelGrid\',\'mlModelByModelGrid\'].forEach(id=>{\n      const container=document.getElementById(id);\n      if(!container) return;\n      const cards=[...container.querySelectorAll(\':scope > .ml-acc-card\')];\n      if(cards.length<2) return;\n      cards.sort((a,b)=>Number(a.dataset.modelRank||999)-Number(b.dataset.modelRank||999));\n      cards.forEach(card=>container.appendChild(card));\n    });\n  }\n\n  function bindClickOnce(){\n    if(window.__mlRankAccordionSingleClickBound) return;\n    window.__mlRankAccordionSingleClickBound=true;\n\n    document.addEventListener(\'click\',function(event){\n      const btn=event.target.closest(\'.ml-acc-head\');\n      if(!btn) return;\n\n      event.preventDefault();\n      event.stopPropagation();\n      if(event.stopImmediatePropagation) event.stopImmediatePropagation();\n\n      const card=btn.closest(\'.ml-acc-card\');\n      if(!card) return;\n\n      card.classList.toggle(\'is-open\');\n    },true);\n  }\n\n  async function run(){\n    addStyle();\n    bindClickOnce();\n\n    const payload=await loadPayload();\n    const ml=payload?.modelos_ml;\n    if(!ml) return;\n\n    const stats=modelStats(ml);\n    const rankMap=new Map(stats.map(s=>[s.model,s.rank]));\n\n    renderPerformance(ml,stats);\n    convertDetailsToCards(rankMap);\n    decorateCards(rankMap);\n    reorderCards();\n  }\n\n  function schedule(){\n    run();\n    setTimeout(run,300);\n    setTimeout(run,900);\n    setTimeout(run,1800);\n    setTimeout(run,3500);\n  }\n\n  document.addEventListener(\'DOMContentLoaded\',schedule);\n  document.addEventListener(\'click\',function(e){\n    if(e.target && (e.target.closest(\'.tab\') || e.target.closest(\'[data-tab]\'))){\n      setTimeout(run,300);\n      setTimeout(run,1000);\n    }\n  });\n\n  schedule();\n})();\n</script>'


SCRIPT_IDS = [
    "ml-performance-rank-enhancer",
    "ml-accordion-collapse-fix",
    "ml-accordion-manual-controller",
    "ml-accordion-div-controller",
    "ml-rank-badge-after-div-fix",
    "ml-accordion-rank-stable",
    "ml-rank-badge-nonintrusive-fix",
    "ml-rank-accordion-single-controller",
]


def remove_script(text: str, script_id: str) -> str:
    return re.sub(
        rf'\n?<script id="{script_id}">.*?</script>\n?',
        '\n',
        text,
        flags=re.S,
    )


def main() -> None:
    if not HTML.exists():
        raise FileNotFoundError(f"Não encontrei {HTML}")

    text = HTML.read_text(encoding='utf-8')

    for script_id in SCRIPT_IDS:
      text = remove_script(text, script_id)

    for old in [
        "${name==='Ensemble'?'open':''}",
        '${name==="Ensemble"?"open":""}',
        "${model.name==='Ensemble'?'open':''}",
        '${model.name==="Ensemble"?"open":""}',
    ]:
        text = text.replace(old, '')

    text = text.replace(" || e.target.closest('summary')", "")
    text = text.replace(' || e.target.closest("summary")', "")
    text = text.replace(" || e.target.closest('button')", "")
    text = text.replace(' || e.target.closest("button")', "")

    idx = text.lower().rfind('</body>')
    if idx >= 0:
        text = text[:idx] + '\n' + SINGLE_JS + '\n' + text[idx:]
    else:
        text = text.rstrip() + '\n' + SINGLE_JS + '\n'

    HTML.write_text(text, encoding='utf-8')

    print('[OK] Aplicado script único: rank + accordion.')
    print('[OK] Removeu scripts antigos conflitantes.')
    print('[OK] Agora o mesmo script cria o badge #rank e controla o abre/fecha.')


if __name__ == '__main__':
    main()
